//! # High-Performance SyncTeX Parser and Reverse Lookup Engine
//!
//! Parses `.synctex.gz` and `.synctex` files generated by TeX engines (Tectonic, pdfLaTeX, XeLaTeX,
//! LuaLaTeX) to provide micro-precise, bidirectional source-to-PDF synchronization.
//!
//! Resolves exact source line numbers for complex elements including table rows, captions,
//! floating figures, embedded images, math environments, and subdocuments.

use flate2::read::GzDecoder;
use std::collections::HashMap;
use std::io::Read;

/// Result of a reverse SyncTeX coordinate lookup.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncLocation {
    /// 1-based source code line number
    pub line: usize,
    /// 0-based character column offset within that line
    pub column: usize,
    /// Associated source file path if resolved
    pub file_path: Option<String>,
}

/// A single synchronization record emitted by the TeX engine.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncRecord {
    /// Record command type: 'g' (glyph), 'h' (hbox), 'v' (vbox), 'x' (void box/image), 'r' (rule), '[' / '(' (containers)
    pub record_type: char,
    /// 1-based file index referencing the Input list in the SyncTeX header
    pub file_tag: usize,
    /// 1-based source code line number
    pub line: usize,
    /// Horizontal coordinate in TeX scaled points (sp) from top-left of page (65536 sp = 1 pt)
    pub x_sp: i64,
    /// Vertical coordinate in TeX scaled points (sp) from top-left of page (baseline)
    pub y_sp: i64,
    /// Box width in scaled points
    pub width_sp: i64,
    /// Box height in scaled points (extends above baseline)
    pub height_sp: i64,
    /// Box depth in scaled points (extends below baseline)
    pub depth_sp: i64,
}

impl SyncRecord {
    /// Calculates the weighted geometric distance score from a click coordinate (in sp) to this record.
    ///
    /// Prioritizes leaf typographic nodes (glyphs, text hboxes, void image frames) over enclosing container boxes.
    pub fn distance_score(&self, click_x: i64, click_y: i64) -> f64 {
        let left = self.x_sp;
        let right = if self.width_sp > 0 {
            self.x_sp + self.width_sp
        } else {
            self.x_sp
        };

        // In TeX, y_sp is the baseline. The box extends upward by height_sp and downward by depth_sp.
        let top = if self.height_sp > 0 {
            self.y_sp - self.height_sp
        } else {
            self.y_sp - (65536 * 10)
        };
        let bottom = if self.depth_sp > 0 {
            self.y_sp + self.depth_sp
        } else {
            self.y_sp + (65536 * 4)
        };

        let dx = if click_x < left {
            (left - click_x) as f64
        } else if click_x > right {
            (click_x - right) as f64
        } else {
            0.0
        };

        let dy = if click_y < top {
            (top - click_y) as f64
        } else if click_y > bottom {
            (click_y - bottom) as f64
        } else {
            0.0
        };

        let sp_pt = 65536.0;
        let dx_pt = dx / sp_pt;
        let dy_pt = dy / sp_pt;

        let is_leaf = matches!(self.record_type, 'g' | 'h' | 'v' | 'x' | 'r' | 'k' | '$');
        let container_penalty = if is_leaf { 0.0 } else { 100_000.0 };

        // Weight vertical distance strongly so clicks anywhere on a line snap to that text row or table cell
        dy_pt * dy_pt * 25.0 + dx_pt * 0.1 + container_penalty
    }

    /// Approximate area of the record's bounding box in sp^2 (used to select the deepest nested sub-element).
    pub fn area_sp(&self) -> i64 {
        let w = self.width_sp.max(65536);
        let h = (self.height_sp + self.depth_sp).max(65536);
        w.saturating_mul(h)
    }
}

/// Parsed SyncTeX database for an entire compiled document.
#[derive(Debug, Clone, Default)]
pub struct SyncTexData {
    /// Mapping from file tag (e.g. 1) to canonical file path or name
    pub files: HashMap<usize, String>,
    /// Mapping from 1-based page number to synchronization records on that page
    pub pages: HashMap<usize, Vec<SyncRecord>>,
}

impl SyncTexData {
    /// Parses SyncTeX data from raw gzip-compressed (`.synctex.gz`) bytes.
    /// Automatically falls back to uncompressed text if the stream is not gzip-encoded.
    pub fn parse_gz(bytes: &[u8]) -> Option<Self> {
        let mut decoder = GzDecoder::new(bytes);
        let mut text = String::new();
        if decoder.read_to_string(&mut text).is_ok() && !text.is_empty() {
            return Self::parse_str(&text);
        }

        // Fallback: check if uncompressed UTF-8
        if let Ok(raw_str) = std::str::from_utf8(bytes) {
            if raw_str.contains("SyncTeX Version:") {
                return Self::parse_str(raw_str);
            }
        }

        None
    }

    /// Parses uncompressed SyncTeX text format.
    pub fn parse_str(text: &str) -> Option<Self> {
        let mut files = HashMap::new();
        let mut pages: HashMap<usize, Vec<SyncRecord>> = HashMap::new();
        let mut current_page: Option<usize> = None;

        for line in text.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }

            // 1. Parse Input file tags: "Input:1:/path/to/main.tex"
            if trimmed.starts_with("Input:") {
                let parts: Vec<&str> = trimmed.splitn(3, ':').collect();
                if parts.len() >= 3 {
                    if let Ok(tag) = parts[1].parse::<usize>() {
                        let path = parts[2].to_string();
                        files.insert(tag, path);
                    }
                }
                continue;
            }

            // 2. Page delimiters: "{1" (begin page 1) and "}1" (end page 1)
            if trimmed.starts_with('{') {
                if let Ok(p_num) = trimmed[1..].trim().parse::<usize>() {
                    current_page = Some(p_num);
                    pages.entry(p_num).or_default();
                }
                continue;
            }
            if trimmed.starts_with('}') {
                current_page = None;
                continue;
            }

            // 3. Parse records on the active page
            if let Some(page_num) = current_page {
                if let Some(record) = Self::parse_record_line(trimmed) {
                    if record.line > 0 {
                        pages.entry(page_num).or_default().push(record);
                    }
                }
            }
        }

        if pages.is_empty() {
            None
        } else {
            Some(Self { files, pages })
        }
    }

    /// Parses a single SyncTeX record line.
    ///
    /// Recognizes:
    /// - `g<tag>,<line>:<x>,<y>` (glyph / point)
    /// - `h<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (horizontal box)
    /// - `v<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (vertical box)
    /// - `x<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (void box / picture)
    /// - `r<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (rule / horizontal line)
    /// - `k<tag>,<line>:<x>,<y>:<w>` (kern)
    /// - `$<tag>,<line>:<x>,<y>` (math)
    /// - `[<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (open hlist box)
    /// - `(<tag>,<line>:<x>,<y>:<w>,<h>,<d>` (open vlist box)
    fn parse_record_line(line_str: &str) -> Option<SyncRecord> {
        let mut chars = line_str.chars();
        let type_char = chars.next()?;
        if !matches!(type_char, 'g' | 'h' | 'v' | 'x' | 'r' | 'k' | '$' | '[' | '(') {
            return None;
        }

        let rest = &line_str[type_char.len_utf8()..];
        let colon_pos = rest.find(':')?;
        let tag_line = &rest[..colon_pos];
        let after_colon = &rest[colon_pos + 1..];

        let comma_pos = tag_line.find(',')?;
        let file_tag: usize = tag_line[..comma_pos].trim().parse().ok()?;
        let line: usize = tag_line[comma_pos + 1..].trim().parse().ok()?;

        let (coords, dimensions) = if let Some(sec_colon) = after_colon.find(':') {
            (&after_colon[..sec_colon], Some(&after_colon[sec_colon + 1..]))
        } else {
            (after_colon, None)
        };

        let coord_comma = coords.find(',')?;
        let x_sp: i64 = coords[..coord_comma].trim().parse().ok()?;
        let y_sp: i64 = coords[coord_comma + 1..].trim().parse().ok()?;

        let mut width_sp: i64 = 0;
        let mut height_sp: i64 = 0;
        let mut depth_sp: i64 = 0;

        if let Some(dim_str) = dimensions {
            let mut parts = dim_str.split(',');
            if let Some(w) = parts.next() {
                width_sp = w.trim().parse().unwrap_or(0);
            }
            if let Some(h) = parts.next() {
                height_sp = h.trim().parse().unwrap_or(0);
            }
            if let Some(d) = parts.next() {
                depth_sp = d.trim().parse().unwrap_or(0);
            }
        }

        Some(SyncRecord {
            record_type: type_char,
            file_tag,
            line,
            x_sp,
            y_sp,
            width_sp,
            height_sp,
            depth_sp,
        })
    }

    /// Finds the closest source line for a double-click position on `page_1based`.
    pub fn find_line_at(
        &self,
        page_1based: usize,
        rel_x: f32,
        rel_y: f32,
        page_width_pt: f32,
        page_height_pt: f32,
    ) -> Option<(usize, Option<String>)> {
        self.find_location_at(page_1based, rel_x, rel_y, page_width_pt, page_height_pt, None)
            .map(|loc| (loc.line, loc.file_path))
    }

    /// Finds the micro-precise source line and character column for a double-click position on `page_1based`.
    ///
    /// - `rel_x`: Normalized horizontal position (0.0 to 1.0 from left edge of paper)
    /// - `rel_y`: Normalized vertical position (0.0 to 1.0 from top edge of paper)
    /// - `page_width_pt`: Page width in typographic points (e.g. 612.0 for Letter)
    /// - `page_height_pt`: Page height in typographic points (e.g. 792.0 for Letter)
    /// - `source_content`: Optional source code string of the document, used to snap to non-blank paragraph
    ///   lines and compute accurate character offsets along wrapped lines.
    pub fn find_location_at(
        &self,
        page_1based: usize,
        rel_x: f32,
        rel_y: f32,
        page_width_pt: f32,
        page_height_pt: f32,
        source_content: Option<&str>,
    ) -> Option<SyncLocation> {
        let records = self.pages.get(&page_1based)?;
        if records.is_empty() {
            return None;
        }

        let sp_per_pt = 65536.0_f64;
        let click_x_sp = (rel_x.clamp(0.0, 1.0) as f64 * page_width_pt as f64 * sp_per_pt) as i64;
        let click_y_sp = (rel_y.clamp(0.0, 1.0) as f64 * page_height_pt as f64 * sp_per_pt) as i64;

        // Group records into visual baseline rows (baselines within ~3.5 pt of each other)
        let baseline_tolerance_sp = (sp_per_pt * 3.5) as i64;
        let mut baseline_groups: Vec<(i64, Vec<&SyncRecord>)> = Vec::new();

        for r in records {
            // Container records '[' and '(' represent outer layout boxes, not typographic elements
            if r.record_type == '[' || r.record_type == '(' {
                continue;
            }
            if let Some(group) = baseline_groups.iter_mut().find(|(y, _)| (r.y_sp - *y).abs() <= baseline_tolerance_sp) {
                group.1.push(r);
            } else {
                baseline_groups.push((r.y_sp, vec![r]));
            }
        }

        if baseline_groups.is_empty() {
            return None;
        }

        struct BaselineRowInfo<'a> {
            y_sp: i64,
            content_line: usize,
            file_tag: usize,
            x_min_sp: i64,
            x_max_sp: i64,
            distance_score: f64,
            _records: Vec<&'a SyncRecord>,
        }

        let mut row_infos: Vec<BaselineRowInfo> = baseline_groups
            .into_iter()
            .map(|(y_sp, mut recs)| {
                recs.sort_by_key(|r| r.x_sp);

                // Find content records (excluding kerns and containers)
                let content_recs: Vec<&&SyncRecord> = recs
                    .iter()
                    .filter(|r| matches!(r.record_type, 'g' | 'h' | 'v' | 'x' | 'r' | '$'))
                    .collect();

                // If content records exist, choose the most representative line number
                // (frequently the line of the glyphs, ignoring trailing paragraph break \parfillskip kerns)
                let (content_line, file_tag) = if !content_recs.is_empty() {
                    let mut line_counts: HashMap<usize, usize> = HashMap::new();
                    for r in &content_recs {
                        *line_counts.entry(r.line).or_default() += 1;
                    }
                    let best_line = line_counts.into_iter().max_by_key(|&(_, count)| count).map(|(l, _)| l).unwrap_or(content_recs[0].line);
                    let tag = content_recs.iter().find(|r| r.line == best_line).map(|r| r.file_tag).unwrap_or(content_recs[0].file_tag);
                    (best_line, tag)
                } else {
                    (recs[0].line, recs[0].file_tag)
                };

                let active_recs = if !content_recs.is_empty() {
                    &content_recs
                } else {
                    &recs.iter().collect::<Vec<_>>()
                };

                let x_min_sp = active_recs.iter().map(|r| r.x_sp).min().unwrap_or(0);
                let x_max_sp = active_recs.iter().map(|r| r.x_sp + r.width_sp.max(0)).max().unwrap_or(x_min_sp);

                let dy_pt = ((y_sp - click_y_sp).abs() as f64) / sp_per_pt;
                let dx_pt = if click_x_sp < x_min_sp {
                    ((x_min_sp - click_x_sp) as f64) / sp_per_pt
                } else if click_x_sp > x_max_sp {
                    ((click_x_sp - x_max_sp) as f64) / sp_per_pt
                } else {
                    0.0
                };

                let distance_score = dy_pt * dy_pt * 25.0 + dx_pt * 0.1;

                BaselineRowInfo {
                    y_sp,
                    content_line,
                    file_tag,
                    x_min_sp,
                    x_max_sp,
                    distance_score,
                    _records: recs,
                }
            })
            .collect();

        row_infos.sort_by(|a, b| a.distance_score.partial_cmp(&b.distance_score).unwrap_or(std::cmp::Ordering::Equal));

        let best_row = row_infos.first()?;
        let mut target_line = best_row.content_line;
        let file_tag = best_row.file_tag;

        // If source_content is available, ensure we don't land on a blank line between paragraphs
        if let Some(src) = source_content {
            let src_lines: Vec<&str> = src.lines().collect();
            if target_line >= 1 && target_line <= src_lines.len() {
                if src_lines[target_line - 1].trim().is_empty() {
                    // Blank line! Snap upward to the nearest non-blank line of that paragraph
                    for l in (1..target_line).rev() {
                        if !src_lines[l - 1].trim().is_empty() {
                            target_line = l;
                            break;
                        }
                    }
                }
            }
        }

        // Compute character column within target_line
        // Find all baseline rows that map to (file_tag, target_line) on this page
        let mut matching_rows: Vec<&BaselineRowInfo> = row_infos
            .iter()
            .filter(|r| r.file_tag == file_tag && r.content_line == target_line)
            .collect();
        matching_rows.sort_by_key(|r| r.y_sp);

        let row_count = matching_rows.len().max(1);
        let row_idx = matching_rows.iter().position(|r| r.y_sp == best_row.y_sp).unwrap_or(0);

        let x_span = (best_row.x_max_sp - best_row.x_min_sp).max(1) as f64;
        let frac_x = ((click_x_sp - best_row.x_min_sp) as f64 / x_span).clamp(0.0, 1.0);

        let overall_frac = (row_idx as f64 + frac_x) / (row_count as f64);
        let overall_frac = overall_frac.clamp(0.0, 1.0);

        let column = if let Some(src) = source_content {
            let line_len = src.lines().nth(target_line.saturating_sub(1)).map(|l| l.chars().count()).unwrap_or(0);
            if line_len == 0 {
                0
            } else {
                ((overall_frac * line_len as f64).round() as usize).min(line_len)
            }
        } else {
            ((overall_frac * 80.0).round() as usize).min(80)
        };

        let file_path = self.files.get(&file_tag).cloned();
        Some(SyncLocation {
            line: target_line,
            column,
            file_path,
        })
    }

    /// Converts a (line, column) in `content` into a 0-based character index.
    pub fn line_col_to_char_index(content: &str, line_1based: usize, col_0based: usize) -> usize {
        if line_1based <= 1 {
            let line_len = content.chars().take_while(|&c| c != '\n' && c != '\r').count();
            return col_0based.min(line_len);
        }

        let mut current_line = 1;
        let mut line_start_char_idx = 0;
        let mut char_count = 0;

        for (idx, ch) in content.chars().enumerate() {
            if ch == '\n' {
                current_line += 1;
                if current_line == line_1based {
                    line_start_char_idx = idx + 1;
                    break;
                }
            }
            char_count = idx + 1;
        }

        if current_line < line_1based {
            return char_count;
        }

        let line_len = content.chars().skip(line_start_char_idx).take_while(|&c| c != '\n' && c != '\r').count();
        line_start_char_idx + col_0based.min(line_len)
    }

    /// Converts a 0-based character index in `content` into (line_1based, column_0based).
    pub fn char_index_to_line_col(content: &str, char_index: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 0;
        for (idx, ch) in content.chars().enumerate() {
            if idx >= char_index {
                break;
            }
            if ch == '\n' {
                line += 1;
                col = 0;
            } else if ch != '\r' {
                col += 1;
            }
        }
        (line, col)
    }

    /// Finds normalized bounding boxes (0.0 to 1.0) on `page_1based` for the specified source line range.
    pub fn find_rects_for_line_range(
        &self,
        page_1based: usize,
        start_line: usize,
        end_line: usize,
        page_width_pt: f32,
        page_height_pt: f32,
    ) -> Vec<egui::Rect> {
        let records = match self.pages.get(&page_1based) {
            Some(r) => r,
            None => return Vec::new(),
        };

        let sp_per_pt = 65536.0_f64;
        let mut raw_boxes = Vec::new();

        for r in records {
            if r.line >= start_line && r.line <= end_line {
                if matches!(r.record_type, 'g' | 'h' | 'v' | 'x' | 'r' | '$') {
                    let w_pt = (r.width_sp.max(65536 * 10) as f64 / sp_per_pt) as f32;
                    let h_pt = ((r.height_sp + r.depth_sp).max(65536 * 10) as f64 / sp_per_pt) as f32;
                    let x_pt = (r.x_sp as f64 / sp_per_pt) as f32;
                    let y_pt = ((r.y_sp - r.height_sp) as f64 / sp_per_pt) as f32;

                    let norm_x = (x_pt / page_width_pt).clamp(0.0, 1.0);
                    let norm_y = (y_pt / page_height_pt).clamp(0.0, 1.0);
                    let norm_w = (w_pt / page_width_pt).clamp(0.005, 1.0);
                    let norm_h = (h_pt / page_height_pt).clamp(0.005, 0.2);

                    raw_boxes.push(egui::Rect::from_min_size(
                        egui::Pos2::new(norm_x, norm_y),
                        egui::vec2(norm_w, norm_h),
                    ));
                }
            }
        }

        raw_boxes
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_synctex_parse_and_lookup() {
        let synctex_content = r#"
SyncTeX Version:1
Input:1:C:\Users\Axel\Documents\laketex\main.tex
Input:2:C:\Users\Axel\Documents\laketex\sub.tex
Output:pdf
Magnification:1000
Unit:1
X Offset:0
Y Offset:0
Content:
!197
{1
[1,1:4736287,46220575:26673152,41484288,0
h1,3:8799519,8865055:983040,0,0
g1,3:11475354,8865055
[1,5:8799519,10776084:22609920,454820,134348
g1,5:19230557,10776084
]
(1,7:8799519,11526468:2565081,550500,235932
g1,7:9192735,11526468
)
(1,8:8799519,12312900:2565081,550500,235932
g1,8:9192735,12312900
)
g1,11:15138817,14000000
}1
!2234
Postamble:
Count:91
"#;

        let synctex = SyncTexData::parse_str(synctex_content).expect("Parse SyncTeX");
        assert_eq!(synctex.files.len(), 2);
        assert_eq!(synctex.pages.get(&1).map(|v| v.len()), Some(10));

        let page_w = 612.0;
        let page_h = 792.0;

        // Line 3: y_sp = 8,865,055 -> rel_y approx 8865055 / (792 * 65536) = 0.1707
        let res3 = synctex.find_line_at(1, 0.2, 0.1707, page_w, page_h);
        assert_eq!(res3.map(|(l, _)| l), Some(3));

        // Line 5: Caption y_sp = 10,776,084 -> rel_y approx 0.2076
        let res5 = synctex.find_line_at(1, 0.35, 0.2076, page_w, page_h);
        assert_eq!(res5.map(|(l, _)| l), Some(5));

        // Line 7: Table Row 1 y_sp = 11,526,468 -> rel_y approx 0.222
        let res7 = synctex.find_line_at(1, 0.2, 0.222, page_w, page_h);
        assert_eq!(res7.map(|(l, _)| l), Some(7));

        // Line 8: Table Row 2 y_sp = 12,312,900 -> rel_y approx 0.237
        let res8 = synctex.find_line_at(1, 0.2, 0.237, page_w, page_h);
        assert_eq!(res8.map(|(l, _)| l), Some(8));
    }

    #[test]
    fn test_real_tectonic_synctex() {
        let synctex_str = r#"
SyncTeX Version:1
Input:1:C:\Users\Axel\test.tex
Output:pdf
Magnification:1000
Unit:1
X Offset:0
Y Offset:0
Content:
!203
{1
[1,8:4736287,46220575:26673152,41484288,0
h1,3:8799519,8865055:983040,0,0
g1,3:11380982,8865055
k1,4:31409439,8865055:16928604
g1,4:31409439,8865055
h1,5:8799519,9651487:983040,0,0
g1,5:12003574,9651487
k1,6:31409439,9651487:16306012
g1,6:31409439,9651487
h1,7:8799519,10437919:983040,0,0
g1,7:11641816,10437919
k1,8:31409439,10437919:16667770
g1,8:31409439,10437919
}1
!892
Postamble:
Count:38
"#;
        let synctex = SyncTexData::parse_str(synctex_str).expect("parse synctex");
        let page_w = 612.0;
        let page_h = 792.0;
        let src = "\\documentclass{article}\n\\begin{document}\nFirst paragraph.\n\nSecond paragraph.\n\nThird paragraph.\n\\end{document}";

        // First paragraph y_sp = 8865055 -> rel_y = 0.1708
        // Clicking at x = 0.25 (middle) and x = 0.75 (trailing margin)
        let res = synctex.find_location_at(1, 0.25, 0.1708, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res.line, 3);
        let res_right = synctex.find_location_at(1, 0.75, 0.1708, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res_right.line, 3);

        // Second paragraph y_sp = 9651487 -> rel_y = 0.1859
        let res2 = synctex.find_location_at(1, 0.25, 0.1859, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res2.line, 5);
        let res2_right = synctex.find_location_at(1, 0.75, 0.1859, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res2_right.line, 5);

        // Third paragraph y_sp = 10437919 -> rel_y = 0.2011
        let res3 = synctex.find_location_at(1, 0.25, 0.2011, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res3.line, 7);
        let res3_right = synctex.find_location_at(1, 0.75, 0.2011, page_w, page_h, Some(src)).unwrap();
        assert_eq!(res3_right.line, 7);
    }
}
